  public boolean endsWithSemicolon(Exprent expr) {
    return !(expr instanceof SwitchHeadExprent ||
      expr instanceof MonitorExprent ||
      expr instanceof IfExprent ||
      (expr instanceof VarExprent && ((VarExprent)expr).isClassDef()));
